ือช้อนกลม (ที่สำหรับตักมัน) คว้านควักเมล็ดออกให้ภายในผลน้ำเต้าเกลี้ยง แต่อย่าให้บางมากนัก (สำหรับภายนอกและจุกจะสลักให้งดงามอย่างไรก็ได้) เสร็จแล้วล้างคว่ำไว้ ล้างหมูแล้วใส่เครื่องบดหรือสับให้ละเอียด ปอกมันแกวฝานหนาสัก 1 เซนติเมตร ใส่หม้อต้มสุกแล้ว ล้างน้ำเย็นหันละเอียด คือหั่นตามยาวเป็นเส้นเล็ก ๆ และหั่นตามขวางให้ถี่ ๆ (ห้ามใส่เครื่องบด การหั่นกับบดเมื่อผสมแล้วเป็นคนละรส) ผักกาดขาวเลื่อยใบออกใช้แต่ก้าน ต้มน้ำให้เดือดพล่านลวกแต่พอสุกแล้วหั่นตามขวางเป็นฝอยบีบน้ำ ออกเสียบ้างล้างต้นหอมให้สะอาดหั่นเล็กๆ ขนาด 5 มิลลิเมตร งาขาวล้างให้หมดกรวดทราย ใส่ครกโขลกให้ละเอียดตักขึ้นใส่ถ้วย ตวงน้ำร้อน 1 ซ้อนโต๊ะ ใส่ในครกล้างงาที่ติดอยู่ใส่ในถ้วยงาคนให้ละลาย แล้วใส่ลงในเนื้อหมูที่สับแล้ว พร้อมด้วยเหล่า เกลือ พริกไท ผงชูรส ซีอิ๊วเล็กน้อย มันแกวนวดให้เข้ากันจนมันจึงใส่ผักกาดขาว ต้นหอมเคล้าให้ทั่ว ตักใส่หม้อคนไปให้สุก ชิมรสเค็มพอดีกับน้ำ เสร็จแล้วบรรจุลงในน้ำเต้าให้เต็มวางในภาชนะทนไฟ แต่ฝานั้นวางไปด้วยไม่ต้องปิด เมื่อสุกแล้วจึงปิด ยกไปตั้งรับประทานได้","**หมายเหตุ** การล้างเนื้อทุกอย่างที่ปรุงอาหารนั้น อย่าตั้งใจจะล้างให้หมดน้ำแดง ๆ เพราะน้ำแดง ๆ นั่นเป็นคุณสมบัติและโอชะของเนื้อ ถ้าล้างจนหมดน้ำแดง ๆ รสของอาหารเหล่านั้นจะชืด ๆ กร่อย ๆ ฉะนั้นเมื่อจะล้างจึงตักน้ำใส่ชาม หยิบชิ้นเนื้อจุ่มและส่ายเล็กน้อยพอให้ผงละออง หลุดไปแค่นั้น ถ้าจะให้ดีจริง ๆ ควรมีผ้าชาวบางไว้ผืนหนึ่ง ชุบน้ำเช็ดดีกว่ามาก น้ำไม่แฉะและเนื้อนิ่มไม่จืดชืด","อนึ่ง ถ้าไม่มีน้ำเต้าผลเล็ก จะใช้น้ำเต้าผลใหญ่หน่อยตัดจุกออก ตัดน้ำเต้าตามขวางเป็น 2 ซีกคล้ายกับเป็นจายกลม ๆ จักปากเป็นปากกระจับ ใส่เนื้อหมูที่ผสมแล้วลง ทำให้หน้านูนขึ้น มีผักชีวางบนหน้าสัก 1 ยอดก็จะดีเหมือนกัน"],"preparation_time":30,"difficulty":"Easy","default_servings":2,"dietary_category":"Other","health_goals":[]},{"source_row_index":158,"name":"น้ำพริกไข่เค็ม","description":"ตำรับอาหารไทยจากชุดข้อมูล PyThaiNLP thai_food_v1.0","instructions":["ปอก ไข่เค็ม เอาใข่ขาวโขลกรวมกับกะปิ 1 กุ้งแห้งป่น กระเทียมเข้ากันดี แล้วใส่ไข่แดง มะอึกซอย บุบพอเข้ากัน ใส่เนื้อปูคนให้เข้ากัน ปรุงรสด้วย น้ำปลา น้ำตาล มะนาว รสตามชอบ บุบพริกเหลือง พริกขี้หนูลอยหน้า","**หมายเหตุ** ใช้เป็นน้ำพริกคลุกข้าวรับประทานกับผักดิบ"],"preparation_time":30,"difficulty":"Easy","default_servings":2,"dietary_category":"Other","health_goals":[]}]$json$::jsonb)
    as x(
      source_row_index integer,
      name text,
      description text,
      instructions jsonb,
      preparation_time integer,
      difficulty text,
      default_servings integer,
      dietary_category public.dietary_preference,
      health_goals text[]
    )
)
insert into public.recipes(
  name, description, instructions, preparation_time, difficulty,
  default_servings, dietary_category, health_goals,
  source_dataset, source_row_index, review_status
)
select
  name, description, instructions, preparation_time, difficulty,
  default_servings, dietary_category, health_goals,
  'pythainlp/thai_food_v1.0', source_row_index, 'unreviewed'
from payload
on conflict (name) do update set
  description = excluded.description,
  instructions = excluded.instructions,
  preparation_time = excluded.preparation_time,
  difficulty = excluded.difficulty,
  default_servings = excluded.default_servings,
  dietary_category = excluded.dietary_category,
  health_goals = excluded.health_goals,
  source_dataset = excluded.source_dataset,
  source_row_index = excluded.source_row_index,
  review_status = excluded.review_status;

delete from public.recipe_ingredients ri
using public.recipes r
where ri.recipe_id = r.id
  and r.source_dataset = 'pythainlp/thai_food_v1.0';

